import { SUBGENRE_DEFAULT_ART, type SubgenreId } from "./subgenres.ts";
import type { Mood, Scene, Story } from "./types.ts";

/**
 * Artwork for a scene. Either a hand-made local illustration (`art`, drawn by the client)
 * or an image file (`url`), for example one generated by an image model.
 */
export interface SceneImage {
  /** Id of a local illustration the client knows how to draw. */
  art?: SceneArtId;
  /** URL of an image file. Takes priority over `art` when the client can load it. */
  url?: string;
  /** Text alternative for screen readers. */
  alt: string;
  /** True only when an image model made the picture. Clients must not call local art "AI-generated". */
  generated: boolean;
}

/** Turns a scene into artwork. Swap the local provider for an image model without touching clients. */
export interface SceneImageProvider {
  readonly name: string;
  imageFor(scene: Scene, story: Story): Promise<SceneImage | null>;
}

export const SCENE_ART = ["lighthouse", "train", "hospital", "house", "forest", "water", "door", "figure"] as const;
export type SceneArtId = (typeof SCENE_ART)[number];

/** Keywords that pick an illustration, checked in order: the first match wins. */
const ART_KEYWORDS: [SceneArtId, RegExp][] = [
  ["lighthouse", /lighthouse|lamp room|beacon|keeper/i],
  ["train", /train|station|platform|rail|carriage|conductor|tunnel/i],
  ["hospital", /hospital|ward|nurse|patient|clinic|asylum|gurney/i],
  ["water", /sea|ocean|lake|shore|wave|river|harbou?r|boat|dock|pier/i],
  ["forest", /forest|wood|tree|field|garden|path|grave|cemetery|moor/i],
  ["door", /door|basement|cellar|stair|hall|corridor|attic|room/i],
  ["house", /house|home|cabin|manor|church|chapel|window|town|village/i],
  ["figure", /figure|man|woman|child|girl|boy|ghost|shadow|someone|stranger/i],
];

const DEFAULT_ART: Record<Mood, SceneArtId> = {
  calm: "house",
  uneasy: "house",
  suspense: "door",
  exploration: "forest",
  threat: "figure",
  revelation: "door",
  ending: "house",
};

/**
 * Picks the local illustration that best fits a scene: a place named in its image prompt first, then the
 * story's sub-genre, then the mood.
 */
export function pickSceneArt(visualPrompt: string, mood: Mood, subgenre?: SubgenreId): SceneArtId {
  return (
    ART_KEYWORDS.find(([, pattern]) => pattern.test(visualPrompt))?.[0] ??
    (subgenre ? SUBGENRE_DEFAULT_ART[subgenre] : undefined) ??
    DEFAULT_ART[mood]
  );
}

/** Free, offline artwork: a local illustration chosen from the scene's image prompt. */
export function createLocalArtProvider(): SceneImageProvider {
  return {
    name: "local-art",
    async imageFor(scene, story) {
      const art = pickSceneArt(scene.visualPrompt, scene.mood, story?.config.subgenre);
      return { art, alt: scene.visualPrompt, generated: false };
    },
  };
}
